function lastChild(n) {
}
function nextSibling(n) {
}
function previousSibling(n) {
}
function childElements(n) {
}
function depthOf(n) {
}
function path(n) {
}
function nodeAt(root, p) {
}
', 'Соседей ищите через индекс в parent.children; путь — список индексов от корня.', '{"driver": "/*__DRIVER__*/\n\nconst el = (tag, attrs = {}, ...kids) => { const n = { type: \"element\", tag, attrs, children: [], parent: null }; for (const k of kids) { const c = typeof k === \"string\" ? { type: \"text\", text: k, parent: null } : k; c.parent = n; n.children.push(c); } return n; };\nconst tx = (text) => ({ type: \"text\", text, parent: null });\nconst page = () => el(\"div\", { id: \"root\", class: \"app\" },\n  el(\"header\", { class: \"top\" }, el(\"h1\", {}, \"Заголовок\"), el(\"nav\", { class: \"menu\" }, el(\"a\", { href: \"/a\", class: \"link active\" }, \"А\"), el(\"a\", { href: \"/b\", class: \"link\" }, \"Б\"))),\n  el(\"main\", {}, el(\"ul\", { id: \"list\" }, el(\"li\", { class: \"item\" }, \"один\"), el(\"li\", { class: \"item done\" }, \"два\"), el(\"li\", { class: \"item\" }, el(\"span\", {}, \"три\"))), el(\"p\", { class: \"note\" }, \"заметка\")),\n);\nconst canon = (x) => (Array.isArray(x) ? x.map(canon) : x && typeof x === \"object\" ? Object.fromEntries(Object.keys(x).sort().map((k) => [k, canon(x[k])])) : x);\nconst names = (nodes) => nodes.map((n) => n.tag + (n.attrs.id ? \"#\" + n.attrs.id : \"\") + (n.attrs.class ? \".\" + n.attrs.class.split(\" \").join(\".\") : \"\")).join(\" \");\nconst root = page();\nconst out = [];\nwalk(root, (n, d) => { if (n.type === \"element\") out.push(\"  \".repeat(d) + n.tag); });\nconsole.log(out.join(\"\\n\"));\nconst list = nodeAt(root, [1, 0]);\nconsole.log(list.tag, list.attrs.id, firstChild(list).tag, lastChild(list).children[0].tag);\nconst second = list.children[1];\nconsole.log(nextSibling(second).attrs.class, previousSibling(second).attrs.class, nextSibling(lastChild(list)), previousSibling(firstChild(list)), nextSibling(root));\nconsole.log(childElements(list.children[2]).map((n) => n.tag).join(), childElements(second).length, depthOf(root), depthOf(second), depthOf(second.children[0]));\nconsole.log(JSON.stringify(path(second)), JSON.stringify(path(root)), nodeAt(root, path(second)) === second, nodeAt(root, [9]), firstChild(second.children[0]));\nlet n = 0; walk(root, () => n++); console.log(n);\n", "expected": ["div", "  header", "    h1", "    nav", "      a", "      a", "  main", "    ul", "      li", "      li", "      li", "        span", "    p", "ul list li span", "item item null null null", "span 0 0 3 4", "[1,0,1] [] true null null", "20"]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'j14-text-content', 2, 'js', 'textContent', 'Напишите функции getTextContent(node) (склейка текста всех текстовых потомков в порядке документа; для текстового узла — его текст) и setTextContent(node, text) (удаляет всех детей элемента и, если text не пуст, добавляет один текстовый узел; у удалённых детей parent = null). Для текстового узла setTextContent меняет его text.', 'function getTextContent(node) {
}
function setTextContent(node, text) {
}
', 'Рекурсивная склейка; при записи — отсоединить прежних детей.', '{"driver": "/*__DRIVER__*/\n\nconst el = (tag, attrs = {}, ...kids) => { const n = { type: \"element\", tag, attrs, children: [], parent: null }; for (const k of kids) { const c = typeof k === \"string\" ? { type: \"text\", text: k, parent: null } : k; c.parent = n; n.children.push(c); } return n; };\nconst tx = (text) => ({ type: \"text\", text, parent: null });\nconst page = () => el(\"div\", { id: \"root\", class: \"app\" },\n  el(\"header\", { class: \"top\" }, el(\"h1\", {}, \"Заголовок\"), el(\"nav\", { class: \"menu\" }, el(\"a\", { href: \"/a\", class: \"link active\" }, \"А\"), el(\"a\", { href: \"/b\", class: \"link\" }, \"Б\"))),\n  el(\"main\", {}, el(\"ul\", { id: \"list\" }, el(\"li\", { class: \"item\" }, \"один\"), el(\"li\", { class: \"item done\" }, \"два\"), el(\"li\", { class: \"item\" }, el(\"span\", {}, \"три\"))), el(\"p\", { class: \"note\" }, \"заметка\")),\n);\nconst canon = (x) => (Array.isArray(x) ? x.map(canon) : x && typeof x === \"object\" ? Object.fromEntries(Object.keys(x).sort().map((k) => [k, canon(x[k])])) : x);\nconst names = (nodes) => nodes.map((n) => n.tag + (n.attrs.id ? \"#\" + n.attrs.id : \"\") + (n.attrs.class ? \".\" + n.attrs.class.split(\" \").join(\".\") : \"\")).join(\" \");\nconst p = el(\"p\", {}, \"Привет, \", el(\"b\", {}, \"мир\"), \"!\", el(\"i\", {}, el(\"u\", {}, \"…\")));\nconsole.log(getTextContent(p), \"|\", getTextContent(p.children[1]), \"|\", getTextContent(tx(\"т\")), \"|\", JSON.stringify(getTextContent(el(\"div\"))));\nconst old = p.children[1];\nsetTextContent(p, \"новый <b>текст</b>\");\nconsole.log(p.children.length, p.children[0].text, p.children[0].parent === p, old.parent, getTextContent(p));\nsetTextContent(p, \"\");\nconsole.log(p.children.length);\nconst t = tx(\"старый\"); setTextContent(t, \"новый\"); console.log(t.text);\n", "expected": ["Привет, мир!… | мир | т | \"\"", "1 новый <b>текст</b> true null новый <b>текст</b>", "0", "новый"]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'j14-serialize', 3, 'js', 'outerHTML: сериализация', 'Напишите функции escapeText(s) (& < > → &amp; &lt; &gt;), escapeAttr(s) (& < > " → &amp; &lt; &gt; &quot;) и outerHTML(node): <тег атрибуты>дети</тег>; атрибуты — в порядке объекта как name="value" (булев атрибут со значением true выводится одним именем; false и null — пропускаются); пустые (void) теги br, hr, img, input, meta, link — без закрывающего и без детей; текст экранируется (кроме содержимого script и style).', 'function escapeText(s) {
}
function escapeAttr(s) {
}
function outerHTML(node) {
}
', 'Рекурсия; в script/style текст не экранируется.', '{"driver": "/*__DRIVER__*/\n\nconst el = (tag, attrs = {}, ...kids) => { const n = { type: \"element\", tag, attrs, children: [], parent: null }; for (const k of kids) { const c = typeof k === \"string\" ? { type: \"text\", text: k, parent: null } : k; c.parent = n; n.children.push(c); } return n; };\nconst tx = (text) => ({ type: \"text\", text, parent: null });\nconst page = () => el(\"div\", { id: \"root\", class: \"app\" },\n  el(\"header\", { class: \"top\" }, el(\"h1\", {}, \"Заголовок\"), el(\"nav\", { class: \"menu\" }, el(\"a\", { href: \"/a\", class: \"link active\" }, \"А\"), el(\"a\", { href: \"/b\", class: \"link\" }, \"Б\"))),\n  el(\"main\", {}, el(\"ul\", { id: \"list\" }, el(\"li\", { class: \"item\" }, \"один\"), el(\"li\", { class: \"item done\" }, \"два\"), el(\"li\", { class: \"item\" }, el(\"span\", {}, \"три\"))), el(\"p\", { class: \"note\" }, \"заметка\")),\n);\nconst canon = (x) => (Array.isArray(x) ? x.map(canon) : x && typeof x === \"object\" ? Object.fromEntries(Object.keys(x).sort().map((k) => [k, canon(x[k])])) : x);\nconst names = (nodes) => nodes.map((n) => n.tag + (n.attrs.id ? \"#\" + n.attrs.id : \"\") + (n.attrs.class ? \".\" + n.attrs.class.split(\" \").join(\".\") : \"\")).join(\" \");\nconsole.log(escapeText(\"a < b && c > d\"), \"|\", escapeAttr(''он сказал \"да\" & <ушёл>''));\nconsole.log(outerHTML(el(\"p\", { class: \"a b\", title: ''x\"y'' }, \"1 < 2 & \", el(\"b\", {}, \"жирный\"), el(\"br\"), \"конец\")));\nconsole.log(outerHTML(el(\"input\", { type: \"checkbox\", checked: true, disabled: false, hidden: null })));\nconsole.log(outerHTML(el(\"div\", {}, el(\"img\", { src: \"a.png\", alt: \"\" }), el(\"hr\"), el(\"script\", {}, \"if (a < b && c) {}\"))));\nconsole.log(outerHTML(el(\"ul\", {}, el(\"li\", {}, \"a\"), el(\"li\", {}, \"\"))), outerHTML(tx(\"<текст>\")));\n", "expected": ["a &lt; b &amp;&amp; c &gt; d | он сказал &quot;да&quot; &amp; &lt;ушёл&gt;", "<p class=\"a b\" title=\"x&quot;y\">1 &lt; 2 &amp; <b>жирный</b><br>конец</p>", "<input type=\"checkbox\" checked>", "<div><img src=\"a.png\" alt=\"\"><hr><script>if (a < b && c) {}</script></div>", "<ul><li>a</li><li></li></ul> &lt;текст&gt;"]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'j14-parse-html', 4, 'js', 'Разбор HTML в дерево', 'Напишите функцию parseHTML(html) для упрощённого HTML: теги с атрибутами (name="value", name=''value'', name=value, name без значения → true), void-теги (br, hr, img, input, meta, link — без закрывающего), текст (с декодированием &amp; &lt; &gt; &quot;), комментарии <!-- … --> пропускаются. Возвращает фрагмент: узел { type: "fragment", children } — потомки с корректными parent. Лишний закрывающий тег игнорируется, незакрытые закрываются в конце. Имена тегов — в нижнем регистре.', 'function parseHTML(html) {
}
', 'Один проход регулярным выражением: комментарий, закрывающий тег, открывающий тег с атрибутами, текст; стек открытых элементов.', '{"driver": "/*__DRIVER__*/\n\nconst el = (tag, attrs = {}, ...kids) => { const n = { type: \"element\", tag, attrs, children: [], parent: null }; for (const k of kids) { const c = typeof k === \"string\" ? { type: \"text\", text: k, parent: null } : k; c.parent = n; n.children.push(c); } return n; };\nconst tx = (text) => ({ type: \"text\", text, parent: null });\nconst page = () => el(\"div\", { id: \"root\", class: \"app\" },\n  el(\"header\", { class: \"top\" }, el(\"h1\", {}, \"Заголовок\"), el(\"nav\", { class: \"menu\" }, el(\"a\", { href: \"/a\", class: \"link active\" }, \"А\"), el(\"a\", { href: \"/b\", class: \"link\" }, \"Б\"))),\n  el(\"main\", {}, el(\"ul\", { id: \"list\" }, el(\"li\", { class: \"item\" }, \"один\"), el(\"li\", { class: \"item done\" }, \"два\"), el(\"li\", { class: \"item\" }, el(\"span\", {}, \"три\"))), el(\"p\", { class: \"note\" }, \"заметка\")),\n);\nconst canon = (x) => (Array.isArray(x) ? x.map(canon) : x && typeof x === \"object\" ? Object.fromEntries(Object.keys(x).sort().map((k) => [k, canon(x[k])])) : x);\nconst names = (nodes) => nodes.map((n) => n.tag + (n.attrs.id ? \"#\" + n.attrs.id : \"\") + (n.attrs.class ? \".\" + n.attrs.class.split(\" \").join(\".\") : \"\")).join(\" \");\nconst dump = (n, d = 0) => (n.type === \"text\" ? \"  \".repeat(d) + JSON.stringify(n.text) : n.type === \"fragment\" ? n.children.map((c) => dump(c, d)).join(\"\\n\") : \"  \".repeat(d) + n.tag + JSON.stringify(n.attrs) + (n.children.length ? \"\\n\" + n.children.map((c) => dump(c, d + 1)).join(\"\\n\") : \"\"));\nconst f = parseHTML(''<div id=main class=\"a b\" data-x=\\''1\\'' hidden><p>1 &lt; 2 &amp; 3</p><!-- коммент --><br><img src=a.png alt=\"\"><INPUT type=text disabled></div>'');\nconsole.log(dump(f));\nconsole.log(f.type, f.children[0].parent === f, f.children[0].children[0].parent === f.children[0]);\nconsole.log(dump(parseHTML(\"текст <b>жирный <i>курсив</b> хвост</i>\")));\nconsole.log(dump(parseHTML(\"</div><p>лишний закрывающий</p><span>незакрытый\")));\nconsole.log(parseHTML(\"\").children.length);\n", "expected": ["div{\"id\":\"main\",\"class\":\"a b\",\"data-x\":\"1\",\"hidden\":true}", "  p{}", "    \"1 < 2 & 3\"", "  br{}", "  img{\"src\":\"a.png\",\"alt\":\"\"}", "  input{\"type\":\"text\",\"disabled\":true}", "fragment true true", "\"текст \"", "b{}", "  \"жирный \"", "  i{}", "    \"курсив\"", "\" хвост\"", "p{}", "  \"лишний закрывающий\"", "span{}", "  \"незакрытый\"", "0"]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'j14-selector-parse', 5, 'js', 'Разбор CSS-селектора', 'Напишите функцию parseSelector(str): поддерживаются составные селекторы: тег, #id, .класс (несколько), [атрибут], [атрибут=значение] (значение в кавычках или без), * и комбинаторы: пробел (потомок), > (ребёнок), + (следующий сосед); запятая — список. Результат: массив альтернатив; альтернатива — массив шагов { combinator: " " | ">" | "+" | null (для первого), tag?, id?, classes: [], attrs: [{ name, value? }] }. Для некорректного селектора бросьте SyntaxError.', 'function parseSelector(str) {
}
', 'Разбейте на альтернативы по запятым, на шаги по комбинаторам, а составной селектор разбирайте регулярными выражениями по префиксу.', '{"driver": "/*__DRIVER__*/\nconst canon = (x) => (Array.isArray(x) ? x.map(canon) : x && typeof x === \"object\" ? Object.fromEntries(Object.keys(x).sort().map((k) => [k, canon(x[k])])) : x);\nconst show = (s) => { try { console.log(JSON.stringify(canon(parseSelector(s)))); } catch (e) { console.log(e.name, e.message); } };\nshow(\"div\");\nshow(\"ul > li.item.done\");\nshow(\"nav a[href=''/b'']:\");\nshow(\"#root .menu a, p.note\");\nshow(\"input[type=text][disabled]\");\nshow(\"h1 + p\");\nshow(\"*\");\nshow(\"a >\");\nshow(\"> a\");\nshow(\"\");\n", "expected": ["[[{\"attrs\":[],\"classes\":[],\"combinator\":null,\"tag\":\"div\"}]]", "[[{\"attrs\":[],\"classes\":[],\"combinator\":null,\"tag\":\"ul\"},{\"attrs\":[],\"classes\":[\"item\",\"done\"],\"combinator\":\">\",\"tag\":\"li\"}]]", "SyntaxError Неверный селектор: a[href=''/b'']:", "[[{\"attrs\":[],\"classes\":[],\"combinator\":null,\"id\":\"root\"},{\"attrs\":[],\"classes\":[\"menu\"],\"combinator\":\" \"},{\"attrs\":[],\"classes\":[],\"combinator\":\" \",\"tag\":\"a\"}],[{\"attrs\":[],\"classes\":[\"note\"],\"combinator\":null,\"tag\":\"p\"}]]", "[[{\"attrs\":[{\"name\":\"type\",\"value\":\"text\"},{\"name\":\"disabled\"}],\"classes\":[],\"combinator\":null,\"tag\":\"input\"}]]", "[[{\"attrs\":[],\"classes\":[],\"combinator\":null,\"tag\":\"h1\"},{\"attrs\":[],\"classes\":[],\"combinator\":\"+\",\"tag\":\"p\"}]]", "[[{\"attrs\":[],\"classes\":[],\"combinator\":null}]]", "SyntaxError Комбинатор без правой части", "SyntaxError Лишний комбинатор", "SyntaxError Пустой селектор"]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'j14-matches', 6, 'js', 'matches и querySelectorAll', 'Селектор — уже разобранный список альтернатив (как в предыдущей задаче; формат: [[{ combinator, tag?, id?, classes, attrs }, …], …]). Напишите matches(node, selectorAlternatives) (узел-элемент подходит, если подходит хотя бы одна альтернатива; комбинаторы: " " — потомок, ">" — ребёнок, "+" — непосредственный следующий сосед-элемент) и querySelectorAll(root, selectorAlternatives) → элементы-потомки root (сам root не включается) в порядке документа; querySelector — первый или null.', 'function matches(node, alts) {
}
function querySelectorAll(root, alts) {
}
function querySelector(root, alts) {
}
', 'Сопоставляйте селектор справа налево: сначала последний шаг с самим узлом, затем комбинатор ведёт к родителю/предку/соседу.', '{"driver": "/*__DRIVER__*/\n\nconst el = (tag, attrs = {}, ...kids) => { const n = { type: \"element\", tag, attrs, children: [], parent: null }; for (const k of kids) { const c = typeof k === \"string\" ? { type: \"text\", text: k, parent: null } : k; c.parent = n; n.children.push(c); } return n; };\nconst tx = (text) => ({ type: \"text\", text, parent: null });\nconst page = () => el(\"div\", { id: \"root\", class: \"app\" },\n  el(\"header\", { class: \"top\" }, el(\"h1\", {}, \"Заголовок\"), el(\"nav\", { class: \"menu\" }, el(\"a\", { href: \"/a\", class: \"link active\" }, \"А\"), el(\"a\", { href: \"/b\", class: \"link\" }, \"Б\"))),\n  el(\"main\", {}, el(\"ul\", { id: \"list\" }, el(\"li\", { class: \"item\" }, \"один\"), el(\"li\", { class: \"item done\" }, \"два\"), el(\"li\", { class: \"item\" }, el(\"span\", {}, \"три\"))), el(\"p\", { class: \"note\" }, \"заметка\")),\n);\nconst canon = (x) => (Array.isArray(x) ? x.map(canon) : x && typeof x === \"object\" ? Object.fromEntries(Object.keys(x).sort().map((k) => [k, canon(x[k])])) : x);\nconst names = (nodes) => nodes.map((n) => n.tag + (n.attrs.id ? \"#\" + n.attrs.id : \"\") + (n.attrs.class ? \".\" + n.attrs.class.split(\" \").join(\".\") : \"\")).join(\" \");\nconst S = (tag, extra = {}) => ({ combinator: null, tag, classes: [], attrs: [], ...extra });\nconst desc = (t, e = {}) => ({ ...S(t, e), combinator: \" \" }), child = (t, e = {}) => ({ ...S(t, e), combinator: \">\" }), adj = (t, e = {}) => ({ ...S(t, e), combinator: \"+\" });\nconst root = page();\nconst q = (alts) => names(querySelectorAll(root, alts));\nconsole.log(q([[S(\"li\")]]));\nconsole.log(q([[S(\"ul\", { id: \"list\" }), child(\"li\", { classes: [\"item\"] })]]));\nconsole.log(q([[S(\"main\"), desc(\"span\")]]));\nconsole.log(q([[S(\"header\"), child(\"a\")]]), \"|\", q([[S(\"nav\"), child(\"a\")]]));\nconsole.log(q([[S(\"li\", { classes: [\"item\", \"done\"] })], [S(\"p\")]]));\nconsole.log(q([[S(\"a\", { attrs: [{ name: \"href\", value: \"/b\" }] })]]), \"|\", q([[S(\"a\", { attrs: [{ name: \"href\" }] })]]));\nconsole.log(q([[S(\"a\", { classes: [\"link\"] }), adj(\"a\")]]), \"|\", q([[S(\"ul\"), adj(\"p\")]]), \"|\", q([[S(\"h1\"), adj(\"nav\")]]));\nconst first = querySelector(root, [[S(\"li\")]]);\nconsole.log(first.children[0].text, querySelector(root, [[S(\"section\")]]), matches(first, [[S(\"ul\"), child(\"li\")]]), matches(first, [[S(\"div\"), child(\"li\")]]), matches(root, [[S(\"div\", { id: \"root\" })]]));\nconsole.log(q([[S(\"div\", { id: \"root\" })]]));\n", "expected": ["li.item li.item.done li.item", "li.item li.item.done li.item", "span", " | a.link.active a.link", "li.item.done p.note", "a.link | a.link.active a.link", "a.link | p.note | nav.menu", "один null true false true"]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'j14-closest-delegate', 7, 'js', 'closest и делегирование', 'Напишите функции closest(node, pred) (сам узел или ближайший предок, для которого pred(n) истинно; иначе null) и findTarget(node, root, pred): поднимается от node до root (включительно не нужно: root исключается) и возвращает ближайший узел, для которого pred истинно, но только если он лежит внутри root; иначе null. И функцию path(node) → массив тегов от корня к узлу (для отладки).', 'function closest(node, pred) {
}
function findTarget(node, root, pred) {
}
function tagPath(node) {
}
', 'Подъём по parent в цикле; для делегирования остановитесь на root.', '{"driver": "/*__DRIVER__*/\n\nconst el = (tag, attrs = {}, ...kids) => { const n = { type: \"element\", tag, attrs, children: [], parent: null }; for (const k of kids) { const c = typeof k === \"string\" ? { type: \"text\", text: k, parent: null } : k; c.parent = n; n.children.push(c); } return n; };\nconst tx = (text) => ({ type: \"text\", text, parent: null });\nconst page = () => el(\"div\", { id: \"root\", class: \"app\" },\n  el(\"header\", { class: \"top\" }, el(\"h1\", {}, \"Заголовок\"), el(\"nav\", { class: \"menu\" }, el(\"a\", { href: \"/a\", class: \"link active\" }, \"А\"), el(\"a\", { href: \"/b\", class: \"link\" }, \"Б\"))),\n  el(\"main\", {}, el(\"ul\", { id: \"list\" }, el(\"li\", { class: \"item\" }, \"один\"), el(\"li\", { class: \"item done\" }, \"два\"), el(\"li\", { class: \"item\" }, el(\"span\", {}, \"три\"))), el(\"p\", { class: \"note\" }, \"заметка\")),\n);\nconst canon = (x) => (Array.isArray(x) ? x.map(canon) : x && typeof x === \"object\" ? Object.fromEntries(Object.keys(x).sort().map((k) => [k, canon(x[k])])) : x);\nconst names = (nodes) => nodes.map((n) => n.tag + (n.attrs.id ? \"#\" + n.attrs.id : \"\") + (n.attrs.class ? \".\" + n.attrs.class.split(\" \").join(\".\") : \"\")).join(\" \");\nconst root = page();\nconst list = root.children[1].children[0];\nconst span = list.children[2].children[0];\nconst text = span.children[0];\nconst isLi = (n) => n.tag === \"li\";\nconsole.log(closest(span, isLi).attrs.class, closest(list.children[0], isLi) === list.children[0], closest(text, isLi) === list.children[2], closest(text, (n) => n.tag === \"table\"), closest(root, (n) => n.tag === \"div\") === root);\nconsole.log(findTarget(text, list, isLi) === list.children[2], findTarget(text, list.children[2], isLi), findTarget(text, root, (n) => n.tag === \"header\"), findTarget(root.children[0].children[0], list, isLi));\nconsole.log(tagPath(text).join(\">\"), tagPath(root).join(\">\"));\n", "expected": ["item true true null true", "true null null null", "div>main>ul>li>span>#text div"]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'j14-live-collection', 8, 'js', 'Живая коллекция', 'Напишите функцию getElementsByClassName(root, cls) → объект-«живая» коллекция: свойство length и метод item(i), а также [Symbol.iterator]; при каждом обращении она заново ищет элементы-потомки root (в порядке документа) с классом cls, поэтому отражает изменения дерева. И snapshot(root, cls) → обычный массив на момент вызова.', 'function getElementsByClassName(root, cls) {
}
function snapshot(root, cls) {
}
', 'Каждый раз пересчитывайте список через обход дерева.', '{"driver": "/*__DRIVER__*/\n\nconst el = (tag, attrs = {}, ...kids) => { const n = { type: \"element\", tag, attrs, children: [], parent: null }; for (const k of kids) { const c = typeof k === \"string\" ? { type: \"text\", text: k, parent: null } : k; c.parent = n; n.children.push(c); } return n; };\nconst tx = (text) => ({ type: \"text\", text, parent: null });\nconst page = () => el(\"div\", { id: \"root\", class: \"app\" },\n  el(\"header\", { class: \"top\" }, el(\"h1\", {}, \"Заголовок\"), el(\"nav\", { class: \"menu\" }, el(\"a\", { href: \"/a\", class: \"link active\" }, \"А\"), el(\"a\", { href: \"/b\", class: \"link\" }, \"Б\"))),\n  el(\"main\", {}, el(\"ul\", { id: \"list\" }, el(\"li\", { class: \"item\" }, \"один\"), el(\"li\", { class: \"item done\" }, \"два\"), el(\"li\", { class: \"item\" }, el(\"span\", {}, \"три\"))), el(\"p\", { class: \"note\" }, \"заметка\")),\n);\nconst canon = (x) => (Array.isArray(x) ? x.map(canon) : x && typeof x === \"object\" ? Object.fromEntries(Object.keys(x).sort().map((k) => [k, canon(x[k])])) : x);\nconst names = (nodes) => nodes.map((n) => n.tag + (n.attrs.id ? \"#\" + n.attrs.id : \"\") + (n.attrs.class ? \".\" + n.attrs.class.split(\" \").join(\".\") : \"\")).join(\" \");\nconst root = page();\nconst list = root.children[1].children[0];\nconst live = getElementsByClassName(root, \"item\");\nconst snap = snapshot(root, \"item\");\nconsole.log(live.length, snap.length, live.item(1).children[0].text, live.item(9));\nconst li = el(\"li\", { class: \"item\" }, \"четыре\");\nli.parent = list; list.children.push(li);\nconsole.log(live.length, snap.length, [...live].map((n) => n.children[0].text ?? \"?\").join());\nlist.children.shift().parent = null;\nconsole.log(live.length, snap.length, live.item(0).children[0].text);\nconsole.log(getElementsByClassName(root, \"nothing\").length, getElementsByClassName(root, \"link\").length);\n", "expected": ["3 3 два null", "4 3 один,два,?,четыре", "3 3 два", "0 2"]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'j14-classlist', 9, 'js', 'classList', 'Напишите функцию classList(el) → объект с методами add(...names), remove(...names), toggle(name, force?) (возвращает итоговое наличие), contains(name), replace(old, new) (true/false), item(i), length и toString(); хранит состояние прямо в el.attrs.class (строка, имена через пробел, без дубликатов; порядок добавления сохраняется). Пустое имя или имя с пробелом — бросьте SyntaxError.', 'function classList(el) {
}
', 'Состояние — строка в el.attrs.class: разбирайте и собирайте при каждой операции.', '{"driver": "/*__DRIVER__*/\n\nconst el = (tag, attrs = {}, ...kids) => { const n = { type: \"element\", tag, attrs, children: [], parent: null }; for (const k of kids) { const c = typeof k === \"string\" ? { type: \"text\", text: k, parent: null } : k; c.parent = n; n.children.push(c); } return n; };\nconst tx = (text) => ({ type: \"text\", text, parent: null });\nconst page = () => el(\"div\", { id: \"root\", class: \"app\" },\n  el(\"header\", { class: \"top\" }, el(\"h1\", {}, \"Заголовок\"), el(\"nav\", { class: \"menu\" }, el(\"a\", { href: \"/a\", class: \"link active\" }, \"А\"), el(\"a\", { href: \"/b\", class: \"link\" }, \"Б\"))),\n  el(\"main\", {}, el(\"ul\", { id: \"list\" }, el(\"li\", { class: \"item\" }, \"один\"), el(\"li\", { class: \"item done\" }, \"два\"), el(\"li\", { class: \"item\" }, el(\"span\", {}, \"три\"))), el(\"p\", { class: \"note\" }, \"заметка\")),\n);\nconst canon = (x) => (Array.isArray(x) ? x.map(canon) : x && typeof x === \"object\" ? Object.fromEntries(Object.keys(x).sort().map((k) => [k, canon(x[k])])) : x);\nconst names = (nodes) => nodes.map((n) => n.tag + (n.attrs.id ? \"#\" + n.attrs.id : \"\") + (n.attrs.class ? \".\" + n.attrs.class.split(\" \").join(\".\") : \"\")).join(\" \");\nconst e = el(\"div\", { class: \"a  b\" });\nconst cl = classList(e);\ncl.add(\"c\", \"a\", \"d\");\nconsole.log(e.attrs.class, cl.length, cl.contains(\"b\"), cl.contains(\"z\"), cl.item(2), cl.item(9));\ncl.remove(\"b\", \"zzz\"); console.log(String(cl));\nconsole.log(cl.toggle(\"x\"), cl.toggle(\"x\"), cl.toggle(\"y\", true), cl.toggle(\"y\", true), cl.toggle(\"a\", false), cl.toggle(\"q\", false), String(cl));\nconsole.log(cl.replace(\"c\", \"C\"), cl.replace(\"zz\", \"k\"), cl.replace(\"d\", \"C\"), String(cl));\nconst bare = el(\"p\", {});\nclassList(bare).add(\"one\");\nconsole.log(bare.attrs.class);\nfor (const bad of [\"\", \"a b\"]) { try { cl.add(bad); } catch (x) { console.log(x.name); } }\n", "expected": ["a b c d 4 true false c null", "a c d", "true false true true false false c d y", "true false true C y", "one", "SyntaxError", "SyntaxError"]}');
